using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Pricing;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void GoldCustomerWithSubtotal100PaysApprovedTotal95()
    {
        var checkout = new Checkout();

        var total = checkout.CalculatePayableTotal(CustomerTier.Gold, 100.00m);

        Assert.Equal(95.00m, total);
    }
}
